from typing import Callable, List

def bool_val(b: bool) -> int:
    """Color value: True -> 1, False -> 0."""
    return 1 if b else 0

def up_count(c: Callable[[int], bool], n: int) -> int:
    return sum(1 for i in range(n) if (not c(i)) and c(i + 1))

def down_count(c: Callable[[int], bool], n: int) -> int:
    return sum(1 for i in range(n) if c(i) and (not c(i + 1)))

def verify_signed_count(bits: List[bool]) -> bool:
    """Check U - D = [c(n)] - [c(0)] for a given color word."""
    n = len(bits) - 1
    c = lambda i: bits[i]
    return (up_count(c, n) - down_count(c, n)) == (bool_val(c(n)) - bool_val(c(0)))

if __name__ == "__main__":
    import itertools
    ok = all(verify_signed_count(list(w))
             for L in range(1, 8) for w in itertools.product([False, True], repeat=L + 1))
    print("Signed count verified on all color words up to length 8:", ok)

from typing import Callable, Optional

def discrete_ivt_up(f: Callable[[int], int], n: int) -> Optional[int]:
    """Given f(0) <= 0 < f(n), locate i with f(i) <= 0 < f(i+1)."""
    assert f(0) <= 0 < f(n)
    for i in range(n):
        if f(i) <= 0 < f(i + 1):
            return i
    return None

if __name__ == "__main__":
    # A discrete root of a monotone integer function.
    f = lambda k: 2 * k - 41   # f(0) = -41, f(21) = 1
    i = discrete_ivt_up(f, 21)
    print(f"sign change at i={i}: f(i)={f(i)}, f(i+1)={f(i+1)}")

