function SIGNED-COUNT(c, n):
    U <- 0; D <- 0
    prev <- c(0)
    for i = 1 to n:
        cur <- c(i)
        if prev = false and cur = true:  U <- U + 1
        else if prev = true and cur = false:  D <- D + 1
        prev <- cur
    assert U - D = value(c(n)) - value(c(0))   // Theorem: signed count
    return (U, D)

function DISCRETE-BROUWER(g, n):
    require g(0) > 0 and g(n) <= n
    for i = 0 to n-1:
        if g(i) - i > 0 and g(i+1) - (i+1) <= 0:
            return i        // i < g(i) and g(i+1) <= i+1
    return NONE            // unreachable under the hypotheses

function UNIFORM-EQUILIBRIUM(A, B):
    rowsums <- [ sum of row i of A  for each i ]
    colsums <- [ sum of column j of B  for each j ]
    if all rowsums equal (= S1) and all colsums equal (= S2):
        return (S1 / numberOfColumns, S2 / numberOfRows)
    return NONE

